INSERT OR REPLACE INTO person VALUES ('284011','John Elkann','ジョン・エルカーン','American-Italian businessman','ジョン・エルカーン（英語: John Jacob Philip "Jaki" Elkann、ジョン・ヤコブ・フィリップ・"ヤキ"・エルカン、1976年4月1日生まれ）は、ニューヨーク出身のユダヤ系イタリア人実業家でフィアット創業家として知られるアニェッリ家のメンバー。 一族が所有するステランティスの会長やアニェッリ家の資産管理会社エクソールの会長兼最高経営責任者、FCAの影響を大きく受けるフェラーリの会長を務める。愛称は「ヤキ（Jaki）」。','ja','ジョン・エルカーン');
