INSERT OR REPLACE INTO person VALUES ('5307199','Drew Houston','','American Internet entrepreneur','Andrew W. Houston (; born March 4, 1983) is an American Internet entrepreneur best known as the co-founder and CEO of Dropbox, an online backup and storage service. According to Forbes, his net worth is about $2 billion. Houston held 24.4% of voting power in Dropbox before the company filed for IPO in February 2018. He has sat on the board of Meta Platforms since February 2020.','en','Drew Houston');
