INSERT OR REPLACE INTO person VALUES ('6962779','Nancy Killefer','','American government consultant','Nancy Killefer (born 1953) is an American government consultant and political figure. She was nominated for the Chief Performance Officer position in the Obama administration in 2009. In 2005 the District of Columbia government had filed a more than $900 tax lien on her home for failure to pay state unemployment tax on household help. She resolved the matter five months after the lien was filed. Killefer withdrew her nomination as CPO on February 3, 2009.','en','Nancy Killefer');
