INSERT OR REPLACE INTO person VALUES ('660297','Dana White','ダナ・ホワイト','American businessman and president of UFC (born 1969)','ダナ・ホワイト（Dana White、1969年7月28日 - ）は、アメリカ合衆国の総合格闘技団体「UFC」のCEO兼社長。Meta社外取締役。数々のスター選手を育て上げている名プロモーターでもある。コネチカット州マンチェスター出身。 UFC日本大会開催（UFC 144）に伴う事前記者会見で、名前の表記についての記者の質問に対して、本人がダナは女の子っぽくなるという理由でデイナを希望してからは、デイナ・ホワイトと表記するメディア媒体もある。','ja','ダナ・ホワイト');
