INSERT OR REPLACE INTO person VALUES ('105038817','Tony Xu','','Chinese American entrepreneur, CEO of DoorDash','Tony Xu (Chinese: 徐迅; pinyin: Xú Xùn; born Xu Xun, 1983/1984) is a Chinese-born American billionaire businessman and the co-founder and CEO of DoorDash. Xu was born in Nanjing, China, and immigrated to the United States with his parents at the age of four. He earned degrees from the University of California, Berkeley, and the Stanford Graduate School of Business. Early in his career, Xu interned at Square, Inc., and worked for McKinsey & Company, eBay, and PayPal.','en','Tony Xu');
