INSERT OR REPLACE INTO person VALUES ('224628','Eddy Cue','エディ・キュー','American businessman','Eduardo H. Cue (born October 23, 1964) is Apple''s senior vice president of services, reporting to CEO John Ternus. Cue oversees Apple''s numerous content stores and products including the iTunes Store, the Apple Books Store, Apple Music, Apple TV, Apple Pay, Siri (until 2017), Apple Maps, iAd, iCloud services, and Apple''s productivity and creativity apps. Cue testified in the antitrust case against Apple for conspiring on eBook pricing.','en','Eddy Cue');
